effect.shader:
void main() {
    vec2 p = acScreenNorm - center;
    float r = length(p);
    float k = pow(r, power) * strength;
    vec2 dir = (r > 1e-5) ? p / r : vec2(0.0);

    float cr = texture(inputImg, acScreenNorm + dir * k * 1.0).r;
    float cg = texture(inputImg, acScreenNorm + dir * k * 0.5).g;
    float cb = texture(inputImg, acScreenNorm + dir * k * 0.0).b;
    float a  = texture(inputImg, acScreenNorm).a;
    fragColor = vec4(cr, cg, cb, a);
}
